 if($_SERVER['REQUEST_METHOD']==='POST')try{verify_csrf();$email=strtolower(trim($_POST['email']??''));$s=$db->prepare('SELECT * FROM users WHERE email=? AND role="admin" LIMIT 1');$s->execute([$email]);$user=$s->fetch();if(!$user||!password_verify($_POST['password']??'',$user['password_hash']))throw new RuntimeException('Incorrect email or password.');$_SESSION['user_id']=$user['id'];$t=$db->prepare('SELECT slug FROM tenants WHERE id=?');$t->execute([$user['tenant_id']]);redirect('/admin/?store='.$t->fetchColumn());}catch(Throwable $e){flash($e->getMessage(),'error');redirect('/admin/login');}
