if($_SERVER['REQUEST_METHOD']==='POST')try{verify_csrf();$action=$_POST['action']??'';$tid=(int)$tenant['id'];
 if($action==='product_save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');if(!$name)throw new RuntimeException('Product name is required.');$existing='';if($id){$q=$db->prepare('SELECT image_url FROM products WHERE id=? AND tenant_id=?');$q->execute([$id,$tid]);$existing=$q->fetchColumn()?:'';}$image=admin_upload('image',$existing);$data=[$name,slug($name),trim($_POST['sku']??''),(float)($_POST['price']??0),(float)($_POST['compare_price']??0),trim($_POST['description']??''),$image,max(0,(int)($_POST['stock']??0)),isset($_POST['active'])?1:0];if($id){$db->prepare('UPDATE products SET name=?,slug=?,sku=?,price=?,compare_price=?,description=?,image_url=?,stock=?,is_active=? WHERE id=? AND tenant_id=?')->execute([...$data,$id,$tid]);}else{$db->prepare('INSERT INTO products (tenant_id,name,slug,sku,price,compare_price,description,image_url,stock,is_active) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute([$tid,...$data]);$id=(int)$db->lastInsertId();}$db->prepare('DELETE FROM product_categories WHERE product_id=?')->execute([$id]);$link=$db->prepare('INSERT IGNORE INTO product_categories (product_id,category_id) VALUES (?,?)');foreach($_POST['categories']??[] as $category)$link->execute([$id,(int)$category]);flash('Product saved and MySQL search data refreshed.');redirect(aurl($tenant,'products'));}
 if($action==='product_delete'){$db->prepare('DELETE FROM products WHERE id=? AND tenant_id=?')->execute([(int)$_POST['id'],$tid]);flash('Product deleted.');redirect(aurl($tenant,'products'));}
 if($action==='category_save'){$name=trim($_POST['name']??'');if(!$name)throw new RuntimeException('Category name is required.');$db->prepare('INSERT INTO categories (tenant_id,name,slug) VALUES (?,?,?)')->execute([$tid,$name,slug($name)]);flash('Category added.');redirect(aurl($tenant,'categories'));}
 if($action==='category_delete'){$db->prepare('DELETE c FROM categories c WHERE c.id=? AND c.tenant_id=?')->execute([(int)$_POST['id'],$tid]);flash('Category deleted.');redirect(aurl($tenant,'categories'));}
 if($action==='banner_save'){$id=(int)($_POST['id']??0);$existing='';if($id){$q=$db->prepare('SELECT image_url FROM banners WHERE id=? AND tenant_id=?');$q->execute([$id,$tid]);$existing=$q->fetchColumn()?:'';}$image=admin_upload('image',$existing);$data=[trim($_POST['title']??''),trim($_POST['subtitle']??''),$image,trim($_POST['cta_label']??'Shop now'),trim($_POST['cta_url']??'/shop'),(int)($_POST['sort_order']??0),isset($_POST['active'])?1:0];if(!$data[0])throw new RuntimeException('Banner title is required.');if($id)$db->prepare('UPDATE banners SET title=?,subtitle=?,image_url=?,cta_label=?,cta_url=?,sort_order=?,is_active=? WHERE id=? AND tenant_id=?')->execute([...$data,$id,$tid]);else$db->prepare('INSERT INTO banners (tenant_id,title,subtitle,image_url,cta_label,cta_url,sort_order,is_active) VALUES (?,?,?,?,?,?,?,?)')->execute([$tid,...$data]);flash('Hero banner saved.');redirect(aurl($tenant,'banners'));}
 if($action==='banner_delete'){$db->prepare('DELETE FROM banners WHERE id=? AND tenant_id=?')->execute([(int)$_POST['id'],$tid]);flash('Banner deleted.');redirect(aurl($tenant,'banners'));}
 if($action==='coupon_save'){$id=(int)($_POST['id']??0);$code=strtoupper(preg_replace('/[^A-Z0-9-]/','',$_POST['code']??''));if(!$code)throw new RuntimeException('Coupon code is required.');$data=[$code,trim($_POST['title']??''),trim($_POST['description']??''),$_POST['discount_type']==='amount'?'amount':'percent',(float)($_POST['discount_value']??0),(float)($_POST['minimum_order']??0),str_replace('T',' ',trim($_POST['starts_at']??''))?:null,str_replace('T',' ',trim($_POST['ends_at']??''))?:null,isset($_POST['active'])?1:0];if($id)$db->prepare('UPDATE coupons SET code=?,title=?,description=?,discount_type=?,discount_value=?,minimum_order=?,starts_at=?,ends_at=?,is_active=? WHERE id=? AND tenant_id=?')->execute([...$data,$id,$tid]);else$db->prepare('INSERT INTO coupons (tenant_id,code,title,description,discount_type,discount_value,minimum_order,starts_at,ends_at,is_active) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute([$tid,...$data]);flash('Coupon saved.');redirect(aurl($tenant,'coupons'));}
 if($action==='coupon_delete'){$db->prepare('DELETE FROM coupons WHERE id=? AND tenant_id=?')->execute([(int)$_POST['id'],$tid]);flash('Coupon deleted.');redirect(aurl($tenant,'coupons'));}
 if($action==='store_save'){$logo=admin_upload('logo',$tenant['logo_url']);$hero=admin_upload('hero',$tenant['hero_image_url']);$theme=in_array($_POST['theme']??'', ['minimal','neomorphism','skeuomorphism','glassmorphism','claymorphism','maximalism','brutalism'],true)?$_POST['theme']:'minimal';$db->prepare('UPDATE tenants SET name=?,tagline=?,description=?,hero_title=?,logo_url=?,hero_image_url=?,primary_color=?,secondary_color=?,accent_color=?,theme=?,show_brand_name=? WHERE id=?')->execute([trim($_POST['name']),trim($_POST['tagline']),trim($_POST['description']),trim($_POST['hero_title']),$logo,$hero,trim($_POST['primary_color']),trim($_POST['secondary_color']),trim($_POST['accent_color']),$theme,isset($_POST['show_brand_name'])?1:0,$tid]);flash('Storefront settings saved.');redirect(aurl($tenant,'storefront'));}
 if($action==='order_status'){$db->prepare('UPDATE orders SET order_status=?,payment_status=? WHERE id=? AND tenant_id=?')->execute([$_POST['order_status'],$_POST['payment_status'],(int)$_POST['id'],$tid]);flash('Order updated.');redirect(aurl($tenant,'orders'));}
